using Microsoft.EntityFrameworkCore;
using SysAdminAssistant.Core;
using SysAdminAssistant.Infrastructure;
static class InvoiceSpecs
{
    public static string Account(){var s="40702810000000000001".ToCharArray();for(int n=0;n<10;n++){s[8]=(char)('0'+n);var value=new string(s);if(InvoiceRecognition.Bank(value,"044525225"))return value;}throw new Exception("fixture");}
    public static string Text(string account)=>$"Поставщик: ООО Тест\nИНН 7707083893\nКПП 773601001\nСчёт № 123 от 26.10.2026\nОплатить до 30.10.2026\nВсего к оплате: 1 234,56 руб.\nР/с: {account}\nБИК 044525225";
    public static InvoiceTemplate Template()=>new(){Name="Fixture",Sender="billing@example.test",Supplier="ООО Тест",TaxId="7707083893",BankAccount=Account(),BankCode="044525225",AutoCreate=true};
    public static InvoiceData Parse(string? text=null,InvoiceTemplate? template=null)=>InvoiceRecognition.Parse(new(text??Text(Account()),"PDF text",1),"billing@example.test","Счёт",new DateTime(2026,10,28,12,0,0,DateTimeKind.Utc),template??Template(),PaymentCalendar.DefaultWeekendMask);
    public static async Task Run(Action<string,bool> check)
    {
        check("Invoice amount Russian separators",InvoiceRecognition.Amount("1 234,56 руб.")==123456);check("Invoice amount English grouping",InvoiceRecognition.Amount("1,234.56 USD")==123456);check("Invoice amount dots grouping",InvoiceRecognition.Amount("1.234,56 EUR")==123456);check("Invoice ambiguous total rejected",InvoiceRecognition.Amount("100 RUB и 200 RUB")==null);check("Invoice negative total rejected",InvoiceRecognition.Amount("-100.00")==null);check("Invoice valid INN checksum",InvoiceRecognition.Inn("7707083893"));check("Invoice invalid INN checksum",!InvoiceRecognition.Inn("7707083894"));check("Invoice bank checksum",InvoiceRecognition.Bank(Account(),"044525225"));check("Invoice invalid account rejected",!InvoiceRecognition.Bank("00000000000000000000","044525225"));
        check("Invoice English named month date",InvoiceRecognition.Date("October 26, 2026")==new DateTime(2026,10,26));check("Invoice Russian named month date",InvoiceRecognition.Date("26 октября 2026")==new DateTime(2026,10,26));check("Invoice ambiguous dates rejected",InvoiceRecognition.Date("26.10.2026 и 30.10.2026")==null);var bounded=Template();bounded.Anchors["Amount"]="Всего: => НДС";check("Invoice field end anchor avoids tax figure",Parse(Text(Account()).Replace("Всего к оплате: 1 234,56 руб.","Всего: 1 234,56 RUB НДС: 200 RUB"),bounded).AmountCents==123456);
        var d=Parse();check("Invoice extracts required data",d.AmountCents==123456&&d.Currency=="RUB"&&d.Number=="123"&&d.InvoiceDate==new DateTime(2026,10,26)&&d.DueDate==new DateTime(2026,10,30));check("Invoice known valid supplier has no issues",d.Issues.Length==0);check("Invoice date is not receipt date",d.InvoiceDate!=d.ReceivedUtc.Date);
        var sample=$"Счёт-заказ № 12345\nот 26.10.2026 | оплатить до 30.10.2026\nПолучатель: ООО Тест\nПлательщик: ООО Покупатель\nИНН 7716946024\nКПП 771501001\nИтого к оплате 1 234,56 руб.\nОбразец заполнения платежного поручения\nБИК 044525225\nСч. № 30101810400000000225\nИНН 7707083893 КПП 773601001\nПолучатель ООО Тест\nСч. № {Account()}";
        var order=Parse(sample);
        check("Invoice order heading and date",order.Number=="12345"&&order.InvoiceDate==new DateTime(2026,10,26));
        check("Invoice payment recipient not payer",order.TaxId=="7707083893"&&order.Kpp=="773601001"&&order.BankAccount==Account()&&order.BankCode=="044525225");
        check("Invoice correspondent from payment table",order.Correspondent=="30101810400000000225");
        var ambiguous=Parse(sample.Replace("ИНН 7707083893 КПП","ИНН 7707083893 ИНН 7717586110 КПП"));
        check("Invoice ambiguous recipient does not use payer automatically",ambiguous.TaxId==""&&ambiguous.Issues.Length>0);
        var split=sample.Replace("Счёт-заказ № 12345\nот", "Счёт-заказ № 12345 Партнёр\nООО Партнёр\nот").Replace("Получатель ООО Тест", "ООО «Тест»\n\nПолучатель");
        var extracted=Parse(split);
        check("Invoice separated order heading and recipient table",extracted.InvoiceDate==new DateTime(2026,10,26)&&extracted.Supplier=="ООО «Тест»");
        var scan=Parse(split.Replace("ООО «Тест»","000 «Тест»"));
        check("Invoice OCR company prefix corrected only in recipient table",scan.Supplier=="ООО «Тест»");
        var noDue=Parse(Text(Account()).Replace("Оплатить до 30.10.2026", ""));check("Invoice no due date needs review",noDue.DueDate==null&&noDue.Issues.Length>0);var t=Template();t.DueDays=5;var calculated=Parse(Text(Account()).Replace("Оплатить до 30.10.2026", ""),t);check("Invoice working day due calculation",calculated.DueDate==new DateTime(2026,11,2)&&calculated.CalculatedDue);
        var changed=Parse(Text(Account()).Replace(Account(),"40702810000000000000"));check("Invoice changed bank requires review",changed.Issues.Any(s=>s.Contains("реквизиты")));var unknown=InvoiceRecognition.Parse(new(Text(Account()),"PDF",1),"x","invoice",DateTime.UtcNow,null,96);check("Invoice new supplier requires template confirmation",unknown.Issues.Length>0);check("Invoice business identity stable across copies",InvoiceRecognition.BusinessKey(d)==InvoiceRecognition.BusinessKey(Parse()));
        check("Invoice ordinary email not a candidate",!InvoiceRecognition.IsCandidate("Привет","Как дела"));check("Invoice English invoice is candidate",InvoiceRecognition.IsCandidate("Invoice 2",""));check("Invoice Cyrillic is candidate",InvoiceRecognition.IsCandidate("Счёт на оплату",""));
        var os=OsUpdateStatus.Parse("{\"pendingCount\":3,\"state\":\"Unknown\",\"items\":[\"KB1\"]}");check("Windows update badge accepts positive pending count and camel case",os.HasUpdates&&os.State=="Available");var previous=new OsUpdateStatus{State="Available",PendingCount=2};check("Windows update query failure retains known available",OsUpdateStatus.Merge(previous,new(){State="Unknown"}).HasUpdates);check("Windows update confirmed current clears icon",!OsUpdateStatus.Merge(previous,new(){State="Current"}).HasUpdates);check("Windows update badge reboot still visible",new OsUpdateStatus{State="Current",RebootRequired=true}.HasUpdates);
        var dir=Path.Combine(Path.GetTempPath(),"SaaInvoiceSpecs-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);
        try{
            var factory=new DatabaseFactory(new AppSettings{SqlitePath=Path.Combine(dir,"invoices.db")});await using(var db=factory.Create()){await db.Database.EnsureCreatedAsync();db.Payments.Add(new Payment{Title="Existing recurring",Repeat=RepeatPeriod.Monthly,DueDate=new DateTime(2026,11,15),AmountKopecks=50000});await db.SaveChangesAsync();await db.Database.ExecuteSqlRawAsync("DROP TABLE sa2_InvoiceAttachment");await db.Database.ExecuteSqlRawAsync("DROP TABLE sa2_InvoiceRecord");await InvoiceSchema.EnsureAsync(db);await InvoiceSchema.EnsureAsync(db);}
            var store=new InvoiceStore(factory);var data=Parse();var bytes=new byte[]{1,2,3,4};var id=await store.Ingest("mail-key",data,"digest-a","fixture.pdf","application/pdf",bytes,true,96);var list=await store.List();check("Invoice auto adds one-off payment",list.Single().Status=="Added"&&list[0].PaymentId!=null);await using(var db=factory.Create()){check("Invoice leaves original recurrence unchanged",await db.Payments.CountAsync()==2&&(await db.Payments.SingleAsync(p=>p.Title=="Existing recurring")).DueDate==new DateTime(2026,11,15));check("Invoice new payment never recurring or paid",!(await db.Payments.SingleAsync(p=>p.Id==list[0].PaymentId)).Paid&&(await db.Payments.SingleAsync(p=>p.Id==list[0].PaymentId)).Repeat==RepeatPeriod.None);}
            check("Invoice list omits raw document body",list[0].Data.RawText=="");var detail=await store.Detail(id);check("Invoice detail retains raw document",detail.Data.RawText.Contains("Поставщик"));var file=await store.File(detail.Files.Single().Id,default);check("Invoice download preserves original bytes",file.Data.SequenceEqual(bytes));
            check("Invoice same UID is idempotent",await store.Ingest("mail-key",Parse(),"digest-a","fixture.pdf","application/pdf",bytes,true,96)==-id);check("Invoice forwarded copy business deduplication",await store.Ingest("forwarded",Parse(),"digest-b","copy.pdf","application/pdf",new byte[]{5,6},true,96)==-id);await using(var db=factory.Create())check("Invoice duplicates never add extra payments",await db.Payments.CountAsync()==2);check("Invoice alternative original retained",(await store.Detail(id)).Files.Length==2);
            var changedBank=Parse();changedBank.BankAccount="40702810000000000000";changedBank.RawText=Text(changedBank.BankAccount);var changedId=await store.Ingest("changed-requisites",changedBank,"changed-digest","changed.pdf","application/pdf",new byte[]{7,8},true,96);check("Invoice same identity with changed bank is not silently deduplicated",changedId>0&&changedId!=id&&(await store.Detail(changedId)).Status=="Review");
            var foreign=Parse();foreign.Number="FOREIGN-1";foreign.Currency="AED";foreign.AmountCents=25000;var foreignId=await store.Ingest("foreign",foreign,"foreign-digest","f.pdf","application/pdf",bytes,true,96);var foreignView=await store.Detail(foreignId);await using(var db=factory.Create())check("Invoice foreign currency is never treated as rubles",(await db.Payments.SingleAsync(p=>p.Id==foreignView.PaymentId)).AmountKopecks==null);
            var untrusted=Parse();untrusted.Number="UNTRUSTED";var untrustedId=await store.Ingest("unknownsender",untrusted,"digest-u","u.pdf","application/pdf",bytes,false,96);check("Invoice untrusted sender cannot auto create",(await store.Detail(untrustedId)).Status=="Review");
            var recurring=Parse();recurring.Number="LINK-1";await using(var db=factory.Create())recurring.RecurringCandidateId=(await db.Payments.SingleAsync(p=>p.Repeat==RepeatPeriod.Monthly)).Id;var linkId=await store.Ingest("recurring",recurring,"digest-r","r.pdf","application/pdf",bytes,true,96);var rv=await store.Detail(linkId);check("Invoice recurring collision requires review",rv.Status=="Review"&&rv.PaymentId==null);await store.Approve(new(rv.Id,rv.Revision,rv.Data,recurring.RecurringCandidateId,new DateTime(2026,10,15)));await using(var db=factory.Create())check("Invoice attaching preserves recurrence and next date",(await db.Payments.SingleAsync(p=>p.Id==recurring.RecurringCandidateId)).DueDate==new DateTime(2026,11,15));check("Invoice linked period retained",(await store.Detail(linkId)).Data.LinkedPeriod==new DateTime(2026,10,15));bool stale=false;try{await store.Approve(new(rv.Id,rv.Revision,rv.Data));}catch(InvoiceConflictException){stale=true;}check("Invoice stale approval rejected",stale);
            var cfg=new InvoiceSettings{AllowedSenders=["billing@example.test"],Templates=[Template()]};var untrustedBefore=await store.Detail(untrustedId);await store.Reprocess(cfg,96,default);check("Invoice reprocessing cannot bypass original sender verification",(await store.Detail(untrustedId)).Status=="Review");
            var missing=Parse();missing.Number="MISSING";missing.DueDate=null;missing.Issues=["Срок не найден"];var pendingId=await store.Ingest("missing",missing,"digest-m","m.pdf","application/pdf",bytes,true,96);var pending=await store.Detail(pendingId);bool rejected=false;try{await store.Approve(new(pending.Id,pending.Revision,pending.Data));}catch(ArgumentException){rejected=true;}check("Invoice incomplete confirmation rejected atomically",rejected&&(await store.Detail(pendingId)).Status=="Review");await store.Reprocess(cfg,96,default);var reprocessed=await store.Detail(pendingId);check("Invoice learning rechecks pending fields",reprocessed.Data.Number=="123");check("Invoice learning detects duplicate instead of creating payment",reprocessed.Status=="Duplicate");check("Invoice payment links expose downloadable documents",(await store.Links(default)).Any(x=>x.PaymentId==list[0].PaymentId&&x.HasDocument));
        }finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();Directory.Delete(dir,true);}
    }
}
